private class CA(c:Context){val p=c.getSharedPreferences("comments_auth",0);fun get()=p.getString("u",null)?.let{u->p.getString("t",null)?.let{CS(u,it)}};fun put(s:CS)=p.edit().putString("u",s.uid).putString("t",s.token).apply()}
private class CR{val b="https://nnnsss-23f2f-default-rtdb.firebaseio.com";val k="AIzaSyAbpqQIxWuEnFolv3lNjNDoPKTGm0mtrxU";fun e(v:String)=URLEncoder.encode(v,"UTF-8");fun path(t:String,w:String,c:String)=if(t=="obra")"comentariosV1/obra/${e(w)}" else "comentariosV1/capitulo/${e(w)}/${e(c)}"
 fun q(url:String,m:String="GET",body:String?=null):JSONObject{val x=URL(url).openConnection() as HttpURLConnection;x.requestMethod=m;x.connectTimeout=15000;x.readTimeout=25000;x.setRequestProperty("Content-Type","application/json");if(body!=null){x.doOutput=true;x.outputStream.use{it.write(body.toByteArray())}};val ok=x.responseCode in 200..299;val s=(if(ok)x.inputStream else x.errorStream)?.bufferedReader()?.use{it.readText()}.orEmpty();x.disconnect();if(!ok)error(if("INVALID_PASSWORD" in s||"EMAIL_NOT_FOUND" in s)"E-mail ou senha incorretos." else "Não foi possível conectar.");return if(s.isBlank()||s=="null")JSONObject()else JSONObject(s)}
