@Composable fun CommentsSection(type:String,workId:String,chapterId:String="",modifier:Modifier=Modifier){val ctx=LocalContext.current;val api=remember{CR()};val auth=remember{CA(ctx)};val scope=rememberCoroutineScope();var session by remember{mutableStateOf(auth.get())};var list by remember{mutableStateOf<List<CC>>(emptyList())};var text by remember{mutableStateOf("")};var sp by remember{mutableStateOf(false)};var busy by remember{mutableStateOf(false)};var err by remember{mutableStateOf("")};var login by remember{mutableStateOf(false)}
 suspend fun load(){busy=true;runCatching{api.list(type,workId,chapterId)}.onSuccess{list=it;err=""}.onFailure{err="Sem internet para carregar os comentários."};busy=false};LaunchedEffect(type,workId,chapterId){load()}
 if(login)LD({login=false}){e,p->scope.launch{runCatching{api.login(e,p)}.onSuccess{session=it;auth.put(it);login=false}.onFailure{err=it.message?:"Não foi possível entrar."}}}
 Column(modifier){Text(if(type=="obra")"Comentários da obra" else "Comentários do capítulo",fontWeight=FontWeight.Black,style=MaterialTheme.typography.headlineSmall);Text("Disponível somente com internet",color=MpMuted);Spacer(Modifier.height(10.dp));Surface(color=MpSurface,shape=RoundedCornerShape(18.dp),border=BorderStroke(1.dp,MpLine)){Column(Modifier.padding(14.dp)){if(session==null){Text("Entre com sua conta para comentar.",color=MpMuted);Button({login=true},Modifier.fillMaxWidth().padding(top=8.dp)){Text("Entrar para comentar")}}else{OutlinedTextField(text,{text=it.take(3000)},Modifier.fillMaxWidth(),label={Text("Escreva um comentário…")},minLines=3);Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){FilterChip(sp,{sp=!sp},{Text(if(sp)"⚠ Spoiler marcado" else "Marcar spoiler")});Spacer(Modifier.weight(1f));Button({scope.launch{busy=true;runCatching{api.send(type,workId,chapterId,text.trim(),sp,session!!)}.onSuccess{text="";sp=false;load()}.onFailure{err="Não foi possível publicar."};busy=false}},enabled=text.isNotBlank()&&!busy){Text("Enviar")}}}}};if(busy)LinearProgressIndicator(Modifier.fillMaxWidth().padding(top=8.dp));if(err.isNotBlank())Text(err,color=MaterialTheme.colorScheme.error,modifier=Modifier.padding(top=8.dp));if(!busy&&list.isEmpty()&&err.isBlank())Text("Ainda não há comentários.",color=MpMuted,modifier=Modifier.padding(14.dp));list.forEach{Card(it)}}}
@Composable private fun Card(x:CC){var show by remember(x.id){mutableStateOf(!x.spoiler)};Surface(Modifier.fillMaxWidth().padding(top=9.dp),color=MpSurface,shape=RoundedCornerShape(16.dp),border=BorderStroke(1.dp,MpLine)){Column(Modifier.padding(14.dp)){Text(x.name,fontWeight=FontWeight.Bold);if(x.spoiler&&!show)Text("⚠ Spoiler — toque para revelar",color=MpMuted,modifier=Modifier.padding(top=8.dp).clickable{show=true})else Text(x.text.ifBlank{"Comentário sem texto."},modifier=Modifier.padding(top=8.dp))}}}
@Composable private fun LD(close:()->Unit,go:(String,String)->Unit){var e by remember{mutableStateOf("")};var p by remember{mutableStateOf("")};AlertDialog(onDismissRequest=close,title={Text("Entrar para comentar")},text={Column{OutlinedTextField(e,{e=it},label={Text("E-mail")});OutlinedTextField(p,{p=it},label={Text("Senha")},visualTransformation=PasswordVisualTransformation())}},confirmButton={Button({go(e,p)},enabled=e.isNotBlank()&&p.isNotBlank()){Text("Entrar")}},dismissButton={TextButton(close){Text("Cancelar")}})}